import { useCallback, useEffect, useRef, useState } from 'react';

interface UseFetchState<T> {
  data: T | null;
  error: Error | null;
  isLoading: boolean;
}

interface UseFetchResult<T> extends UseFetchState<T> {
  refetch: () => void;
}

export function useFetch<T>(
  url: string | null,
  options?: RequestInit
): UseFetchResult<T> {
  const [state, setState] = useState<UseFetchState<T>>({
    data: null,
    error: null,
    isLoading: !!url,
  });
  // Stash options in a ref so an inline object literal doesn't
  // retrigger the effect; callers who need to vary options pass
  // primitives (method, a stable header object) or bump a "version" key.
  const optionsRef = useRef(options);
  optionsRef.current = options;
  const [reloadToken, setReloadToken] = useState(0);

  const refetch = useCallback(() => setReloadToken((t) => t + 1), []);

  useEffect(() => {
    if (!url) {
      setState({ data: null, error: null, isLoading: false });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, isLoading: true, error: null }));

    fetch(url, optionsRef.current)
      .then(async (res) => {
        if (!res.ok) throw new Error(`Request failed: ${res.status}`);
        return res.json() as Promise<T>;
      })
      .then((json) => {
        if (!cancelled) setState({ data: json, error: null, isLoading: false });
      })
      .catch((err: Error) => {
        if (!cancelled) setState({ data: null, error: err, isLoading: false });
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url, reloadToken]);

  return { ...state, refetch };
}

// Usage:
function CoachList() {
  const { data, error, isLoading, refetch } = useFetch<Coach[]>('/api/coaches');
  if (isLoading) return <Spinner />;
  if (error) return <ErrorState message={error.message} onRetry={refetch} />;
  return <CoachTable coaches={data ?? []} />;
}

