function ListingsGrid({ filters }: { filters: SearchFilters }) {
  const [listings, setListings] = useState<Listing[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    setIsLoading(true);
    setError(null);

    const params = new URLSearchParams(filters as Record<string, string>);
    fetch(`/api/listings?${params}`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Search failed: ${res.status}`);
        return res.json();
      })
      .then((data) => {
        setListings(data.results);
        setIsLoading(false);
      })
      .catch((err) => {
        if (err.name === 'AbortError') return; // superseded request, ignore silently
        setError('Could not load listings. Please try again.');
        setIsLoading(false);
      });

    return () => controller.abort();
  }, [filters.crop, filters.region, filters.minPrice, filters.maxPrice]);

  if (error) return <ErrorState message={error} />;
  return (
    <div>
      {isLoading && <Spinner overlay />}
      <Grid items={listings} dimmed={isLoading} />
    </div>
  );
}

