import { NextRequest, NextResponse } from 'next/server';

export function middleware(request: NextRequest) {
  const token = request.cookies.get('session')?.value;

  if (!token) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('redirectTo', request.nextUrl.pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/dashboard/:path*'],
};

// app/login/page.tsx
export default function LoginPage({
  searchParams,
}: {
  searchParams: { redirectTo?: string };
}) {
  async function handleLogin(formData: FormData) {
    'use server';
    const session = await authenticate(formData);
    cookies().set('session', session.token, { httpOnly: true, secure: true });
    redirect(searchParams.redirectTo ?? '/dashboard');
  }
  return <LoginForm action={handleLogin} />;
}

// app/dashboard/layout.tsx — no client-side auth check needed anymore;
// middleware guarantees we never render this for an unauthenticated request.
export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  return <div className="dashboard-shell">{children}</div>;
}

