// lib/permissions.ts
export type Role = 'coach' | 'learner' | 'admin' | 'support-agent';
export type Permission =
  | 'session:cancel'
  | 'session:reschedule'
  | 'session:join'
  | 'session:review'
  | 'session:force-refund';

const ROLE_PERMISSIONS: Record<Role, Permission[]> = {
  coach: ['session:cancel', 'session:reschedule'],
  learner: ['session:join', 'session:review'],
  admin: ['session:cancel', 'session:reschedule', 'session:join', 'session:force-refund'],
  'support-agent': ['session:cancel', 'session:reschedule'],
};

export function can(user: { role: Role }, permission: Permission): boolean {
  return ROLE_PERMISSIONS[user.role]?.includes(permission) ?? false;
}

// hooks/usePermission.ts
export function usePermission(permission: Permission): boolean {
  const { user } = useAuth();
  return can(user, permission);
}

// components/Can.tsx — declarative gate, renders nothing (not just hidden) when denied
export function Can({ perform, children }: { perform: Permission; children: React.ReactNode }) {
  const allowed = usePermission(perform);
  return allowed ? <>{children}</> : null;
}

