import { useForm, FormProvider, useFormContext } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const farmDetailsSchema = z.object({
  farmName: z.string().min(2, 'Farm name is required'),
  location: z.string().min(2, 'Location is required'),
});
const produceSchema = z.object({
  crop: z.string().min(1, 'Select a crop'),
  pricePerKg: z.coerce.number().positive('Price must be greater than 0'),
});
const fullSchema = farmDetailsSchema.merge(produceSchema);
type ListingFormValues = z.infer<typeof fullSchema>;

const STEPS = [
  { id: 1, schema: farmDetailsSchema, fields: ['farmName', 'location'] as const },
  { id: 2, schema: produceSchema, fields: ['crop', 'pricePerKg'] as const },
  { id: 3, schema: fullSchema, fields: [] as const },
];

function ListingWizard() {
  const [step, setStep] = useState(1);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const methods = useForm<ListingFormValues>({
    resolver: zodResolver(fullSchema),
    mode: 'onBlur',
    defaultValues: { farmName: '', location: '', crop: '', pricePerKg: 0 },
  });
  const { trigger, handleSubmit, formState } = methods;

  async function goNext() {
    const currentFields = STEPS.find((s) => s.id === step)!.fields;
    const valid = await trigger(currentFields as any); // validates only this step's fields
    if (valid) setStep((s) => s + 1);
  }

  const onSubmit = async (values: ListingFormValues) => {
    setSubmitError(null);
    try {
      const res = await fetch('/api/listings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(values),
      });
      if (!res.ok) throw new Error('Server rejected the listing');
      // navigate to success state
    } catch (err) {
      setSubmitError('Could not submit your listing. Please try again.');
    }
  };

  return (
    <FormProvider {...methods}>
      <form onSubmit={handleSubmit(onSubmit)}>
        {step === 1 && <FarmDetailsStep onNext={goNext} />}
        {step === 2 && <ProduceStep onBack={() => setStep(1)} onNext={goNext} />}
        {step === 3 && (
          <ReviewStep
            onBack={() => setStep(2)}
            isSubmitting={formState.isSubmitting}
            submitError={submitError}
          />
        )}
      </form>
    </FormProvider>
  );
}

function FarmDetailsStep({ onNext }: { onNext: () => void }) {
  const { register, formState: { errors } } = useFormContext<ListingFormValues>();
  return (
    <div>
      <input {...register('farmName')} />
      {errors.farmName && <p className="text-red-500">{errors.farmName.message}</p>}
      <input {...register('location')} />
      {errors.location && <p className="text-red-500">{errors.location.message}</p>}
      <button type="button" onClick={onNext}>Next</button>
    </div>
  );
}

