function SessionRow({ session }: { session: Session }) {
  const [attended, setAttended] = useState(session.attended);
  const [isPending, setIsPending] = useState(false);
  const { showToast } = useToast();

  async function handleToggle() {
    if (isPending) return; // guard against double-taps
    const previous = attended;
    const next = !attended;

    setAttended(next);       // optimistic update
    setIsPending(true);

    try {
      const res = await fetch(`/api/sessions/${session.id}/attendance`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ attended: next }),
      });
      if (!res.ok) throw new Error('Update rejected');

      const serverState: { attended: boolean } = await res.json();
      setAttended(serverState.attended); // reconcile with authoritative value
    } catch (err) {
      setAttended(previous); // rollback
      showToast({ type: 'error', message: 'Could not update attendance. Please try again.' });
    } finally {
      setIsPending(false);
    }
  }

  return (
    <label className={isPending ? 'opacity-60' : ''}>
      <input
        type="checkbox"
        checked={attended}
        disabled={isPending}
        onChange={handleToggle}
      />
      Attended
    </label>
  );
}

