// components/AsyncBoundary.tsx
type AsyncState<T> =
  | { status: 'loading' }
  | { status: 'error'; error: Error }
  | { status: 'empty' }
  | { status: 'success'; data: T };

interface AsyncBoundaryProps<T> {
  state: AsyncState<T>;
  onRetry?: () => void;
  loadingFallback?: React.ReactNode;
  emptyFallback?: React.ReactNode;
  errorFallback?: (error: Error, retry?: () => void) => React.ReactNode;
  children: (data: T) => React.ReactNode;
}

export function AsyncBoundary<T>({
  state,
  onRetry,
  loadingFallback = <Spinner />,
  emptyFallback = <EmptyState />,
  errorFallback,
  children,
}: AsyncBoundaryProps<T>) {
  switch (state.status) {
    case 'loading':
      return <>{loadingFallback}</>;
    case 'error':
      return errorFallback
        ? <>{errorFallback(state.error, onRetry)}</>
        : <ErrorState message={state.error.message} onRetry={onRetry} />;
    case 'empty':
      return <>{emptyFallback}</>;
    case 'success':
      return <>{children(state.data)}</>;
  }
}

// Helper to derive AsyncState from a common { data, error, isLoading } fetch hook
function toAsyncState<T>(
  result: { data: T[] | null; error: Error | null; isLoading: boolean },
  isEmpty: (data: T[]) => boolean = (d) => d.length === 0
): AsyncState<T[]> {
  if (result.isLoading) return { status: 'loading' };
  if (result.error) return { status: 'error', error: result.error };
  if (!result.data || isEmpty(result.data)) return { status: 'empty' };
  return { status: 'success', data: result.data };
}

// PurchaseOrdersList.tsx
function PurchaseOrdersList() {
  const result = useFetch<PurchaseOrder[]>('/api/purchase-orders');
  const state = toAsyncState(result);

  return (
    <AsyncBoundary
      state={state}
      onRetry={result.refetch}
      emptyFallback={
        <EmptyState
          title="No purchase orders yet"
          action={<Button href="/purchase-orders/new">Create one</Button>}
        />
      }
    >
      {(orders) => (
        <ul>{orders.map((po) => <li key={po.id}>{po.orderNumber}</li>)}</ul>
      )}
    </AsyncBoundary>
  );
}

