type ConnectionStatus = 'connecting' | 'connected' | 'reconnecting' | 'disconnected';

function useSocketStatus(url: string, maxRetries = 5) {
  const [status, setStatus] = useState<ConnectionStatus>('connecting');
  const retryCountRef = useRef(0);
  const socketRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    let isUnmounted = false;
    let reconnectTimer: ReturnType<typeof setTimeout>;

    function connect() {
      const socket = new WebSocket(url);
      socketRef.current = socket;

      socket.onopen = () => {
        if (isUnmounted) return;
        retryCountRef.current = 0;
        setStatus('connected');
      };

      socket.onclose = () => {
        if (isUnmounted) return;
        if (retryCountRef.current >= maxRetries) {
          setStatus('disconnected'); // gave up — needs explicit user action
          return;
        }
        setStatus('reconnecting');
        const delay = Math.min(1000 * 2 ** retryCountRef.current, 30_000);
        retryCountRef.current += 1;
        reconnectTimer = setTimeout(connect, delay);
      };

      socket.onerror = () => socket.close(); // triggers onclose, which drives retry logic
    }

    connect();
    return () => {
      isUnmounted = true;
      clearTimeout(reconnectTimer);
      socketRef.current?.close();
    };
  }, [url, maxRetries]);

  const retryNow = useCallback(() => {
    retryCountRef.current = 0;
    setStatus('connecting');
    // Triggers the effect's cleanup + rerun via a url-independent nudge is awkward;
    // simplest is exposing connect() itself — see lab 10 for the full reconnect hook.
  }, []);

  return { status, retryNow };
}

function ConnectionBanner() {
  const { status } = useSocketStatus('wss://api.example.com/live');
  if (status === 'connected') return null;
  if (status === 'reconnecting') {
    return <div className="banner banner-warning">Reconnecting…</div>;
  }
  if (status === 'disconnected') {
    return (
      <div className="banner banner-error">
        Connection lost. Live updates paused.
        <button onClick={() => window.location.reload()}>Refresh</button>
      </div>
    );
  }
  return <div className="banner banner-info">Connecting…</div>;
}

