type ConnectionStatus = 'connecting' | 'connected' | 'reconnecting' | 'disconnected';

interface UseWebSocketOptions {
  maxRetries?: number;
  maxDelayMs?: number;
}

export function useWebSocket(url: string, options: UseWebSocketOptions = {}) {
  const { maxRetries = 8, maxDelayMs = 30_000 } = options;
  const [status, setStatus] = useState<ConnectionStatus>('connecting');
  const socketRef = useRef<WebSocket | null>(null);
  const retryCountRef = useRef(0);
  const queueRef = useRef<string[]>([]);
  const timerRef = useRef<ReturnType<typeof setTimeout>>();
  const isUnmountedRef = useRef(false);

  const connect = useCallback(() => {
    clearTimeout(timerRef.current);
    setStatus((prev) => (prev === 'connected' ? prev : 'connecting'));

    const socket = new WebSocket(url);
    socketRef.current = socket;

    socket.onopen = () => {
      if (isUnmountedRef.current) return;
      retryCountRef.current = 0;
      setStatus('connected');
      // flush queued messages now that we're actually open
      queueRef.current.forEach((msg) => socket.send(msg));
      queueRef.current = [];
    };

    socket.onclose = () => {
      if (isUnmountedRef.current) return;
      if (retryCountRef.current >= maxRetries) {
        setStatus('disconnected');
        return;
      }
      setStatus('reconnecting');
      const delay = Math.min(1000 * 2 ** retryCountRef.current, maxDelayMs);
      retryCountRef.current += 1;
      timerRef.current = setTimeout(connect, delay);
    };

    socket.onerror = () => socket.close();
  }, [url, maxRetries, maxDelayMs]);

  useEffect(() => {
    isUnmountedRef.current = false;
    connect();
    return () => {
      isUnmountedRef.current = true;
      clearTimeout(timerRef.current);
      socketRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((message: string) => {
    const socket = socketRef.current;
    if (socket && socket.readyState === WebSocket.OPEN) {
      socket.send(message);
    } else {
      queueRef.current.push(message); // flushed on next successful open
    }
  }, []);

  const retryNow = useCallback(() => {
    retryCountRef.current = 0;
    connect();
  }, [connect]);

  return { status, send, retryNow };
}

