// components/RelativeDueDate.tsx — a small client component used ONLY for the
// time-sensitive part; the rest of FilingCard can stay a Server Component.
'use client';

import { useEffect, useState } from 'react';

function daysRemainingFrom(dueDateMs: number, nowMs: number): number {
  return Math.ceil((dueDateMs - nowMs) / (1000 * 60 * 60 * 24));
}

export function RelativeDueDate({ dueDate }: { dueDate: string }) {
  const dueDateMs = new Date(dueDate).getTime();

  // On the very first client render (which must match SSR output),
  // render a neutral, deterministic placeholder — never Date.now().
  const [daysRemaining, setDaysRemaining] = useState<number | null>(null);

  useEffect(() => {
    // Runs only on the client, after hydration — safe to read the real clock here.
    setDaysRemaining(daysRemainingFrom(dueDateMs, Date.now()));
    const interval = setInterval(() => {
      setDaysRemaining(daysRemainingFrom(dueDateMs, Date.now()));
    }, 60_000); // refresh every minute
    return () => clearInterval(interval);
  }, [dueDateMs]);

  if (daysRemaining === null) {
    // Matches exactly what the server rendered — no mismatch possible,
    // because the server never computed a time-dependent number either.
    return <span className="due-date-placeholder">Calculating…</span>;
  }
  return <span>Filing due in {daysRemaining} days</span>;
}

