// components/PaymentStatusPoller.tsx
'use client';

type PaymentStatus = 'pending' | 'succeeded' | 'failed';

export function PaymentStatusPoller({ orderId }: { orderId: string }) {
  const [status, setStatus] = useState<PaymentStatus>('pending');
  const [isRetrying, setIsRetrying] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let attempts = 0;
    const maxAttempts = 20; // ~1 minute at 3s intervals

    async function poll() {
      if (cancelled) return;
      try {
        // Authoritative source: our backend, which only knows "succeeded"
        // once Razorpay/Stripe's webhook has actually confirmed the charge.
        const res = await fetch(`/api/orders/${orderId}/status`);
        const data: { status: PaymentStatus } = await res.json();
        if (cancelled) return;

        setStatus(data.status);
        if (data.status === 'pending' && attempts < maxAttempts) {
          attempts += 1;
          setTimeout(poll, 3000);
        }
      } catch {
        if (!cancelled) setTimeout(poll, 3000);
      }
    }
    poll();
    return () => {
      cancelled = true;
    };
  }, [orderId]);

  async function handleRetry() {
    setIsRetrying(true);
    // Re-uses the SAME order/payment-intent id server-side so a retry
    // resumes the existing order instead of creating a duplicate charge.
    const res = await fetch(`/api/orders/${orderId}/retry-checkout`, { method: 'POST' });
    const { checkoutUrl } = await res.json();
    window.location.href = checkoutUrl; // back to Stripe/Razorpay hosted checkout
  }

  if (status === 'succeeded') {
    return <h1>Payment successful! Your session is booked.</h1>;
  }
  if (status === 'failed') {
    return (
      <div>
        <h1>Payment failed.</h1>
        <button onClick={handleRetry} disabled={isRetrying}>
          {isRetrying ? 'Redirecting…' : 'Try again'}
        </button>
      </div>
    );
  }
  return (
    <div>
      <h1>Confirming your payment…</h1>
      <p>This can take a few seconds. Don't close this page.</p>
    </div>
  );
}

