import { useRouter, useSearchParams, usePathname } from 'next/navigation';
import { useCallback, useMemo } from 'react';

function useTableUrlState() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // Single source of truth: derive current state from the URL on every render.
  const warehouse = searchParams.get('warehouse') ?? 'all';
  const sortBy = searchParams.get('sort') ?? 'name';
  const page = Number(searchParams.get('page') ?? '1');

  const setParams = useCallback(
    (updates: Record<string, string | number>, { replace = false } = {}) => {
      const next = new URLSearchParams(searchParams.toString());
      Object.entries(updates).forEach(([key, value]) => next.set(key, String(value)));
      const url = `${pathname}?${next.toString()}`;
      if (replace) {
        router.replace(url, { scroll: false });
      } else {
        router.push(url, { scroll: false });
      }
    },
    [pathname, router, searchParams]
  );

  const setWarehouse = useCallback(
    (value: string) => setParams({ warehouse: value, page: 1 }), // filter change resets page
    [setParams]
  );
  const setSortBy = useCallback(
    (value: string) => setParams({ sort: value, page: 1 }),
    [setParams]
  );
  const setPage = useCallback(
    (value: number) => setParams({ page: value }),
    [setParams]
  );

  return { warehouse, sortBy, page, setWarehouse, setSortBy, setPage };
}

