'use client';
import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';

function usePortalTarget(id: string) {
  const [target, setTarget] = useState<HTMLElement | null>(null);
  useEffect(() => {
    // Only touches document inside an effect — never at module scope or
    // during render — so this is safe under Next.js SSR.
    let node = document.getElementById(id);
    if (!node) {
      node = document.createElement('div');
      node.id = id;
      document.body.appendChild(node);
    }
    setTarget(node);
  }, [id]);
  return target;
}

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  contentRef: React.RefObject<HTMLDivElement>;
  children: React.ReactNode;
}

export function Modal({ isOpen, onClose, contentRef, children }: ModalProps) {
  const portalTarget = usePortalTarget('modal-root');
  const mouseDownOnBackdrop = useRef(false);

  if (!isOpen || !portalTarget) return null;

  return createPortal(
    <div
      className="modal-backdrop"
      onMouseDown={(e) => { mouseDownOnBackdrop.current = e.target === e.currentTarget; }}
      onMouseUp={(e) => {
        if (mouseDownOnBackdrop.current && e.target === e.currentTarget) onClose();
      }}
      role="presentation"
    >
      <div className="modal-content" role="dialog" aria-modal="true" ref={contentRef}>
        {children}
      </div>
    </div>,
    portalTarget
  );
}

// Usage
function DeleteListingButton({ listingId }: { listingId: string }) {
  const { isOpen, open, close, contentRef } = useModal();
  return (
    <>
      <button onClick={open}>Delete</button>
      <Modal isOpen={isOpen} onClose={close} contentRef={contentRef}>
        <p>Are you sure you want to delete this listing?</p>
        <button onClick={() => { confirmDelete(listingId); close(); }}>Confirm</button>
      </Modal>
    </>
  );
}
